window.CHAPTERS = [{"number": 1, "title": "Unit 1 · Pathway 1 · Intro to Programming", "questions": [{"id": "google-u1-p1-q1", "text": "Which of the following variable declarations is valid?", "type": "single", "options": [{"id": "A", "text": "var hello: Int? = \"\""}, {"id": "B", "text": "String \"hello\" = hello"}, {"id": "C", "text": "val hello = \"hello\""}, {"id": "D", "text": "hello: String = \"hello\""}], "answers": ["C"], "plain": true, "note": "", "explanation": "val hello = \"hello\" suy ra kiểu String.", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-1-pathway-1/android-basics-compose-unit-1-pathway-1?hl=en", "title": "Google · Unit 1 · Pathway 1 · Đáp án đã kiểm chứng"}}, {"id": "google-u1-p1-q2", "text": "It is considered best practice to declare a variable that will not change using var instead of val .", "type": "single", "options": [{"id": "A", "text": "True"}, {"id": "B", "text": "False"}], "answers": ["B"], "plain": true, "note": "", "explanation": "Biến không gán lại nên dùng val.", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-1-pathway-1/android-basics-compose-unit-1-pathway-1?hl=en", "title": "Google · Unit 1 · Pathway 1 · Đáp án đã kiểm chứng"}}, {"id": "google-u1-p1-q3", "text": "Which of the following are valid ways to update a variable?", "type": "multi", "options": [{"id": "A", "text": "total++"}, {"id": "B", "text": "total - 1"}, {"id": "C", "text": "total--"}, {"id": "D", "text": "total = total + 1"}], "answers": ["A", "C", "D"], "plain": true, "note": "", "explanation": "total - 1 chỉ tạo kết quả, không gán lại. ++, -- và phép gán mới cập nhật biến.", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-1-pathway-1/android-basics-compose-unit-1-pathway-1?hl=en", "title": "Google · Unit 1 · Pathway 1 · Đáp án đã kiểm chứng"}}, {"id": "google-u1-p1-q4", "text": "In Kotlin, comments can be single or multi-line and are ignored by the compiler.", "type": "single", "options": [{"id": "A", "text": "True"}, {"id": "B", "text": "False"}], "answers": ["A"], "plain": true, "note": "", "explanation": "Kotlin hỗ trợ // và /* ... */.", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-1-pathway-1/android-basics-compose-unit-1-pathway-1?hl=en", "title": "Google · Unit 1 · Pathway 1 · Đáp án đã kiểm chứng"}}, {"id": "google-u1-p1-q5", "text": "Which of the following is not a data type in Kotlin?", "type": "single", "options": [{"id": "A", "text": "String"}, {"id": "B", "text": "Decimal"}, {"id": "C", "text": "Int"}, {"id": "D", "text": "Boolean"}], "answers": ["B"], "plain": true, "note": "", "explanation": "Kotlin không có kiểu Decimal dựng sẵn.", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-1-pathway-1/android-basics-compose-unit-1-pathway-1?hl=en", "title": "Google · Unit 1 · Pathway 1 · Đáp án đã kiểm chứng"}}, {"id": "google-u1-p1-q6", "text": "Float also represents a decimal, but is less precise than Double .", "type": "single", "options": [{"id": "A", "text": "True"}, {"id": "B", "text": "False"}], "answers": ["A"], "plain": true, "note": "", "explanation": "Float có độ chính xác thấp hơn Double.", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-1-pathway-1/android-basics-compose-unit-1-pathway-1?hl=en", "title": "Google · Unit 1 · Pathway 1 · Đáp án đã kiểm chứng"}}, {"id": "google-u1-p1-q7", "text": "In Kotlin, the entrypoint of a program is the ___.", "type": "single", "options": [{"id": "A", "text": "println() statement"}, {"id": "B", "text": "val variable"}, {"id": "C", "text": "main() function"}, {"id": "D", "text": "return statement"}], "answers": ["C"], "plain": true, "note": "", "explanation": "main() là điểm bắt đầu chương trình Kotlin.", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-1-pathway-1/android-basics-compose-unit-1-pathway-1?hl=en", "title": "Google · Unit 1 · Pathway 1 · Đáp án đã kiểm chứng"}}, {"id": "google-u1-p1-q8", "text": "Which of the following are true about function return values?", "type": "multi", "options": [{"id": "A", "text": "If a function does not specify a return type, the return type is Unit ."}, {"id": "B", "text": "A return value can be stored in a variable."}, {"id": "C", "text": "Functions with a return type of Unit must include a return statement."}, {"id": "D", "text": "A return value's type must match the return type of a function."}], "answers": ["A", "B", "D"], "plain": true, "note": "", "explanation": "Theo ngữ cảnh hàm thân khối ở bài nhập môn, không khai báo kiểu trả về thì dùng Unit. Ngoại lệ cần nhớ: hàm thân biểu thức như fun double(x: Int) = x * 2 được suy ra kiểu trả về. Giá trị trả về có thể lưu vào biến và phải phù hợp kiểu.", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-1-pathway-1/android-basics-compose-unit-1-pathway-1?hl=en", "title": "Google · Unit 1 · Pathway 1 · Đáp án đã kiểm chứng"}}, {"id": "google-u1-p1-q9", "text": "Which of the following are true about functions?", "type": "multi", "options": [{"id": "A", "text": "Functions can take parameters, or variables as inputs."}, {"id": "B", "text": "Function parameters are required to have default arguments."}, {"id": "C", "text": "When calling a function with parameters, the values passed in are called arguments."}, {"id": "D", "text": "Breaking up your code into separate functions makes your code easier to maintain."}], "answers": ["A", "C", "D"], "plain": true, "note": "", "explanation": "Tham số không bắt buộc có giá trị mặc định. Các nhận định còn lại đúng.", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-1-pathway-1/android-basics-compose-unit-1-pathway-1?hl=en", "title": "Google · Unit 1 · Pathway 1 · Đáp án đã kiểm chứng"}}, {"id": "google-u1-p1-q10", "text": "With named arguments, you can change the order in which you pass arguments into a function.", "type": "single", "options": [{"id": "A", "text": "True"}, {"id": "B", "text": "False"}], "answers": ["A"], "plain": true, "note": "", "explanation": "Named arguments cho phép chỉ rõ tên tham số thay vì phụ thuộc vị trí.", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-1-pathway-1/android-basics-compose-unit-1-pathway-1?hl=en", "title": "Google · Unit 1 · Pathway 1 · Đáp án đã kiểm chứng"}}]}, {"number": 2, "title": "Unit 1 · Pathway 2 · Set up Android Studio", "questions": [{"id": "google-u1-p2-q1", "text": "What does IDE stand for?", "type": "single", "options": [{"id": "A", "text": "Integrated Development Environment"}, {"id": "B", "text": "Independent Design Environment"}, {"id": "C", "text": "Ideal Developer Environment"}, {"id": "D", "text": "Intelligent Design Environment"}], "answers": ["A"], "plain": true, "note": "", "explanation": "IDE là Integrated Development Environment.", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-1-pathway-2/android-basics-compose-unit-1-pathway-2?hl=en", "title": "Google · Unit 1 · Pathway 2 · Đáp án đã kiểm chứng"}}, {"id": "google-u1-p2-q2", "text": "Which of the following are advantages of using Android Studio?", "type": "multi", "options": [{"id": "A", "text": "It can help prevent typos and other mistakes in your code."}, {"id": "B", "text": "It comes with a virtual device called an emulator that can run your app."}, {"id": "C", "text": "It can show you a real-time preview of how your app will look on-screen while you code."}, {"id": "D", "text": "It can automatically translate your app into other languages."}], "answers": ["A", "B", "C"], "plain": true, "note": "", "explanation": "Android Studio hỗ trợ kiểm tra code, emulator và preview. Tự dịch toàn bộ ứng dụng không phải chức năng mặc định.", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-1-pathway-2/android-basics-compose-unit-1-pathway-2?hl=en", "title": "Google · Unit 1 · Pathway 2 · Đáp án đã kiểm chứng"}}, {"id": "google-u1-p2-q3", "text": "What is the purpose of using a virtual device, or emulator, in Android Studio?", "type": "single", "options": [{"id": "A", "text": "To show a variety of error messages to users"}, {"id": "B", "text": "To experiment with app code safely"}, {"id": "C", "text": "To test your app on a device without having that physical device"}, {"id": "D", "text": "To see what your app looks like in a web browser"}], "answers": ["C"], "plain": true, "note": "", "explanation": "Emulator mô phỏng thiết bị để chạy thử mà không cần máy thật.", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-1-pathway-2/android-basics-compose-unit-1-pathway-2?hl=en", "title": "Google · Unit 1 · Pathway 2 · Đáp án đã kiểm chứng"}}, {"id": "google-u1-p2-q4", "text": "In Android Studio, what is a project template good for?", "type": "multi", "options": [{"id": "A", "text": "It causes Android Studio to download files faster."}, {"id": "B", "text": "It makes getting started on building a new app faster."}, {"id": "C", "text": "It provides a structure that follows best practices."}, {"id": "D", "text": "It is the only way to build apps that can be previewed in Android Studio."}, {"id": "E", "text": "It makes building a new app less error-prone by pre-populating the project with some app code."}], "answers": ["B", "C", "E"], "plain": true, "note": "", "explanation": "Template cung cấp mã khởi đầu và cấu trúc theo thực hành tốt.", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-1-pathway-2/android-basics-compose-unit-1-pathway-2?hl=en", "title": "Google · Unit 1 · Pathway 2 · Đáp án đã kiểm chứng"}}, {"id": "google-u1-p2-q5", "text": "How do you create a new project in Android Studio?", "type": "single", "options": [{"id": "A", "text": "A. Log out of Android Studio, and navigate to your project folder to find instructions."}, {"id": "B", "text": "B. If you have a project already open, select File > New > New Project from the Android Studio menu."}, {"id": "C", "text": "C. In the “Welcome to Android Studio” window, click “Start a new Android Studio project.”"}, {"id": "D", "text": "D. Create a new file on your computer, and title it “New Android Studio Project.\""}, {"id": "E", "text": "Both B and C are ways to create a new project in Android Studio."}, {"id": "F", "text": "None of the above"}], "answers": ["E"], "plain": true, "note": "", "explanation": "Cả menu New Project và màn hình Welcome đều tạo được dự án.", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-1-pathway-2/android-basics-compose-unit-1-pathway-2?hl=en", "title": "Google · Unit 1 · Pathway 2 · Đáp án đã kiểm chứng"}}, {"id": "google-u1-p2-q6", "text": "___ is a function that is used to define a layout in your app using Composable functions.", "type": "single", "options": [{"id": "A", "text": "ComponentActivity()"}, {"id": "B", "text": "onCreate()"}, {"id": "C", "text": "DefaultPreview()"}, {"id": "D", "text": "setContent()"}], "answers": ["D"], "plain": true, "note": "", "explanation": "setContent nhận nội dung UI được mô tả bởi composable.", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-1-pathway-2/android-basics-compose-unit-1-pathway-2?hl=en", "title": "Google · Unit 1 · Pathway 2 · Đáp án đã kiểm chứng"}}, {"id": "google-u1-p2-q7", "text": "A Compose function requires the @Composable annotation.", "type": "single", "options": [{"id": "A", "text": "True"}, {"id": "B", "text": "False"}], "answers": ["A"], "plain": true, "note": "", "explanation": "Composable cần được đánh dấu @Composable.", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-1-pathway-2/android-basics-compose-unit-1-pathway-2?hl=en", "title": "Google · Unit 1 · Pathway 2 · Đáp án đã kiểm chứng"}}, {"id": "google-u1-p2-q8", "text": "A ___ is a Composable that has a background color and can contain other Composables.", "type": "single", "options": [{"id": "A", "text": "Color"}, {"id": "B", "text": "Container"}, {"id": "C", "text": "Surface"}, {"id": "D", "text": "Box"}], "answers": ["C"], "plain": true, "note": "", "explanation": "Surface có thể cung cấp màu nền và bao composable con.", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-1-pathway-2/android-basics-compose-unit-1-pathway-2?hl=en", "title": "Google · Unit 1 · Pathway 2 · Đáp án đã kiểm chứng"}}, {"id": "google-u1-p2-q9", "text": "Padding is an example of a ___", "type": "single", "options": [{"id": "A", "text": "Property"}, {"id": "B", "text": "Composable"}, {"id": "C", "text": "Attribute"}, {"id": "D", "text": "Modifier"}], "answers": ["D"], "plain": true, "note": "", "explanation": "Padding được thiết lập qua Modifier.", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-1-pathway-2/android-basics-compose-unit-1-pathway-2?hl=en", "title": "Google · Unit 1 · Pathway 2 · Đáp án đã kiểm chứng"}}, {"id": "google-u1-p2-q10", "text": "Which of the following is false about Compose?", "type": "single", "options": [{"id": "A", "text": "The Empty Compose Activity template is used to create a simple app."}, {"id": "B", "text": "Layouts can be viewed in the Preview window, without actually running your app."}, {"id": "C", "text": "All elements and themes in a Compose app are contained in a Surface."}, {"id": "D", "text": "Themes, such as GreetingCardTheme allow you to style Composables."}], "answers": ["C"], "plain": true, "note": "", "explanation": "Theme có thể bao Surface, nên không có yêu cầu mọi phần tử và theme đều nằm trong Surface.", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-1-pathway-2/android-basics-compose-unit-1-pathway-2?hl=en", "title": "Google · Unit 1 · Pathway 2 · Đáp án đã kiểm chứng"}}]}, {"number": 3, "title": "Unit 1 · Pathway 3 · Build a basic layout", "questions": [{"id": "google-u1-p3-q1", "text": "What is Jetpack Compose?", "type": "single", "options": [{"id": "A", "text": "A Modern toolkit to develop Android UI"}, {"id": "B", "text": "Toolkit to design libraries"}, {"id": "C", "text": "Database Interface"}, {"id": "D", "text": "Plugin to build APK"}], "answers": ["A"], "plain": true, "note": "", "explanation": "Jetpack Compose là toolkit xây dựng giao diện Android.", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-1-pathway-3/android-basics-compose-unit-1-pathway-3?hl=en", "title": "Google · Unit 1 · Pathway 3 · Đáp án đã kiểm chứng"}}, {"id": "google-u1-p3-q2", "text": "Composable functions are the basic building block of Compose.", "type": "single", "options": [{"id": "A", "text": "True"}, {"id": "B", "text": "False"}], "answers": ["A"], "plain": true, "note": "", "explanation": "Composable mô tả các thành phần giao diện.", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-1-pathway-3/android-basics-compose-unit-1-pathway-3?hl=en", "title": "Google · Unit 1 · Pathway 3 · Đáp án đã kiểm chứng"}}, {"id": "google-u1-p3-q3", "text": "What annotation is used to annotate a Composable function?", "type": "single", "options": [{"id": "A", "text": "@Annotation"}, {"id": "B", "text": "@ComposableFunction"}, {"id": "C", "text": "@Composable"}, {"id": "D", "text": "@Preview"}], "answers": ["C"], "plain": true, "note": "", "explanation": "Annotation đúng là @Composable.", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-1-pathway-3/android-basics-compose-unit-1-pathway-3?hl=en", "title": "Google · Unit 1 · Pathway 3 · Đáp án đã kiểm chứng"}}, {"id": "google-u1-p3-q4", "text": "The basic standard layout elements in Compose are:", "type": "multi", "options": [{"id": "A", "text": "Column"}, {"id": "B", "text": "Row"}, {"id": "C", "text": "Text"}, {"id": "D", "text": "Box"}], "answers": ["A", "B", "D"], "plain": true, "note": "", "explanation": "Column, Row và Box bố trí các phần tử. Text dùng để hiển thị văn bản.", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-1-pathway-3/android-basics-compose-unit-1-pathway-3?hl=en", "title": "Google · Unit 1 · Pathway 3 · Đáp án đã kiểm chứng"}}, {"id": "google-u1-p3-q5", "text": "What is the tool window for importing, creating, managing, and using resources in your app?", "type": "single", "options": [{"id": "A", "text": "Application Manager"}, {"id": "B", "text": "Resource Manager"}, {"id": "C", "text": "Resource Tool"}, {"id": "D", "text": "Layout Manager"}], "answers": ["B"], "plain": true, "note": "", "explanation": "Resource Manager quản lý tài nguyên ứng dụng.", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-1-pathway-3/android-basics-compose-unit-1-pathway-3?hl=en", "title": "Google · Unit 1 · Pathway 3 · Đáp án đã kiểm chứng"}}, {"id": "google-u1-p3-q6", "text": "Which class is an automatically generated class by Android that contains the IDs of all resources in the project.", "type": "single", "options": [{"id": "A", "text": "The Android class"}, {"id": "B", "text": "The Resource class"}, {"id": "C", "text": "The R Class"}, {"id": "D", "text": "The ResourceID class"}], "answers": ["C"], "plain": true, "note": "", "explanation": "Lớp R chứa các resource ID được sinh tự động.", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-1-pathway-3/android-basics-compose-unit-1-pathway-3?hl=en", "title": "Google · Unit 1 · Pathway 3 · Đáp án đã kiểm chứng"}}, {"id": "google-u1-p3-q7", "text": "Which function is used is to load a drawable image resource.", "type": "single", "options": [{"id": "A", "text": "The stringResource() function"}, {"id": "B", "text": "The painterResource() function"}, {"id": "C", "text": "The ImageResource() function"}, {"id": "D", "text": "The loadResource() function"}], "answers": ["B"], "plain": true, "note": "", "explanation": "painterResource nạp drawable thành Painter.", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-1-pathway-3/android-basics-compose-unit-1-pathway-3?hl=en", "title": "Google · Unit 1 · Pathway 3 · Đáp án đã kiểm chứng"}}, {"id": "google-u1-p3-q8", "text": "What is the function parameter used to add accessibility text, used by talkback?", "type": "single", "options": [{"id": "A", "text": "accessibilityText"}, {"id": "B", "text": "contentText"}, {"id": "C", "text": "accessibilityDescription"}, {"id": "D", "text": "contentDescription"}], "answers": ["D"], "plain": true, "note": "", "explanation": "contentDescription cung cấp mô tả cho công nghệ hỗ trợ.", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-1-pathway-3/android-basics-compose-unit-1-pathway-3?hl=en", "title": "Google · Unit 1 · Pathway 3 · Đáp án đã kiểm chứng"}}, {"id": "google-u1-p3-q9", "text": "The Box layout stacks the UI elements on top of one another.", "type": "single", "options": [{"id": "A", "text": "True"}, {"id": "B", "text": "False"}], "answers": ["A"], "plain": true, "note": "", "explanation": "Box xếp các phần tử chồng lên nhau.", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-1-pathway-3/android-basics-compose-unit-1-pathway-3?hl=en", "title": "Google · Unit 1 · Pathway 3 · Đáp án đã kiểm chứng"}}, {"id": "google-u1-p3-q10", "text": "What parameter is used to align the child element to the beginning of the parent?", "type": "single", "options": [{"id": "A", "text": "Alignment.End"}, {"id": "B", "text": "Alignment.Begin"}, {"id": "C", "text": "Alignment.Start"}, {"id": "D", "text": "Alignment.Top"}], "answers": ["C"], "plain": true, "note": "", "explanation": "Alignment.Start căn về cạnh bắt đầu theo hướng bố cục.", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-1-pathway-3/android-basics-compose-unit-1-pathway-3?hl=en", "title": "Google · Unit 1 · Pathway 3 · Đáp án đã kiểm chứng"}}]}, {"number": 4, "title": "Unit 2 · Pathway 1 · Kotlin fundamentals", "questions": [{"id": "google-u2-p1-q1", "text": "The following code will print \"Divisible by 5\" if number is equal to 25 .\n\nif (number % 10 == 0) {\n  println(\"Divisible by 10\")\n} else if (number == 5) {\n  println(\"Divisible by 5\")\n}", "type": "single", "options": [{"id": "A", "text": "true"}, {"id": "B", "text": "false"}], "answers": ["B"], "plain": true, "note": "", "explanation": "Với number = 25, 25 % 10 khác 0 và 25 không bằng 5. Không nhánh nào in dòng Divisible by 5.", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-2-pathway-1/android-basics-compose-unit-2-pathway-1?hl=en", "title": "Google · Unit 2 · Pathway 1 · Đáp án đã kiểm chứng"}}, {"id": "google-u2-p1-q2", "text": "Which of the following conditions are satisfied when x = 5 ?", "type": "multi", "options": [{"id": "A", "text": "x == 5"}, {"id": "B", "text": "x in 1..5"}, {"id": "C", "text": "x is Int"}, {"id": "D", "text": "x % 5"}], "answers": ["A", "B", "C"], "plain": true, "note": "", "explanation": "5 bằng 5, nằm trong 1..5 và có kiểu Int. x % 5 là biểu thức số, không phải Boolean.", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-2-pathway-1/android-basics-compose-unit-2-pathway-1?hl=en", "title": "Google · Unit 2 · Pathway 1 · Đáp án đã kiểm chứng"}}, {"id": "google-u2-p1-q3", "text": "Which is not a basic concept of object-oriented programming", "type": "single", "options": [{"id": "A", "text": "Abstraction"}, {"id": "B", "text": "Readability"}, {"id": "C", "text": "Inheritance"}, {"id": "D", "text": "Polymorphism"}], "answers": ["B"], "plain": true, "note": "", "explanation": "Abstraction, inheritance và polymorphism là khái niệm OOP. Readability là chất lượng mã.", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-2-pathway-1/android-basics-compose-unit-2-pathway-1?hl=en", "title": "Google · Unit 2 · Pathway 1 · Đáp án đã kiểm chứng"}}, {"id": "google-u2-p1-q4", "text": "Which are the four visibility modifiers in Kotlin?", "type": "single", "options": [{"id": "A", "text": "public , private , protected , abstract"}, {"id": "B", "text": "static , override , internal , external"}, {"id": "C", "text": "private , protected , public , internal"}, {"id": "D", "text": "public , protected , static , internal"}], "answers": ["C"], "plain": true, "note": "", "explanation": "Bốn visibility modifier là private, protected, public, internal.", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-2-pathway-1/android-basics-compose-unit-2-pathway-1?hl=en", "title": "Google · Unit 2 · Pathway 1 · Đáp án đã kiểm chứng"}}, {"id": "google-u2-p1-q5", "text": "The ___ keyword is used to call a method from the parent class.", "type": "single", "options": [{"id": "A", "text": "this"}, {"id": "B", "text": "super"}, {"id": "C", "text": "parent"}, {"id": "D", "text": "self"}], "answers": ["B"], "plain": true, "note": "", "explanation": "super tham chiếu phần triển khai của lớp cha.", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-2-pathway-1/android-basics-compose-unit-2-pathway-1?hl=en", "title": "Google · Unit 2 · Pathway 1 · Đáp án đã kiểm chứng"}}, {"id": "google-u2-p1-q6", "text": "A(n) ___ defines properties or methods that a class needs to implement.", "type": "single", "options": [{"id": "A", "text": "Delegate"}, {"id": "B", "text": "Generic type"}, {"id": "C", "text": "Interface"}, {"id": "D", "text": "Subclass"}], "answers": ["C"], "plain": true, "note": "", "explanation": "Interface quy định hợp đồng mà lớp có thể triển khai.", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-2-pathway-1/android-basics-compose-unit-2-pathway-1?hl=en", "title": "Google · Unit 2 · Pathway 1 · Đáp án đã kiểm chứng"}}, {"id": "google-u2-p1-q7", "text": "Which of the following is best represented by a nullable type?", "type": "single", "options": [{"id": "A", "text": "The number of followers (0 or more) in a social media app."}, {"id": "B", "text": "An optional profile picture."}, {"id": "C", "text": "A username that must be at least one character."}, {"id": "D", "text": "A unique ID given to every user."}], "answers": ["B"], "plain": true, "note": "", "explanation": "Ảnh đại diện tùy chọn có thể vắng mặt, phù hợp nullable.", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-2-pathway-1/android-basics-compose-unit-2-pathway-1?hl=en", "title": "Google · Unit 2 · Pathway 1 · Đáp án đã kiểm chứng"}}, {"id": "google-u2-p1-q8", "text": "The ___ operator allows you to call a method only if the object is non-null.", "type": "single", "options": [{"id": "A", "text": "."}, {"id": "B", "text": "!!"}, {"id": "C", "text": "?:"}, {"id": "D", "text": "?."}], "answers": ["D"], "plain": true, "note": "", "explanation": "?. chỉ gọi thành viên nếu đối tượng khác null.", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-2-pathway-1/android-basics-compose-unit-2-pathway-1?hl=en", "title": "Google · Unit 2 · Pathway 1 · Đáp án đã kiểm chứng"}}, {"id": "google-u2-p1-q9", "text": "Which is not true of functions in Kotlin?", "type": "single", "options": [{"id": "A", "text": "A function can be changed to another data type, and vice versa."}, {"id": "B", "text": "A function can be returned from another function."}, {"id": "C", "text": "A function can take another function as a parameter."}, {"id": "D", "text": "A function has a data type, such as (Int) -> Unit ."}], "answers": ["A"], "plain": true, "note": "", "explanation": "Hàm là giá trị có kiểu hàm, nhưng không có phép chuyển đổi tùy ý giữa hàm và mọi kiểu dữ liệu.", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-2-pathway-1/android-basics-compose-unit-2-pathway-1?hl=en", "title": "Google · Unit 2 · Pathway 1 · Đáp án đã kiểm chứng"}}, {"id": "google-u2-p1-q10", "text": "A function literal is another name for a ___", "type": "single", "options": [{"id": "A", "text": "Function type"}, {"id": "B", "text": "Lambda expression"}, {"id": "C", "text": "Function reference"}, {"id": "D", "text": "Trailing lambda"}], "answers": ["B"], "plain": true, "note": "", "explanation": "Function literal có thể được biểu diễn bằng lambda expression.", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-2-pathway-1/android-basics-compose-unit-2-pathway-1?hl=en", "title": "Google · Unit 2 · Pathway 1 · Đáp án đã kiểm chứng"}}]}, {"number": 5, "title": "Unit 2 · Pathway 2 · Add a button to an app", "questions": [{"id": "google-u2-p2-q1", "text": "Use a ___ Composable to display an image", "type": "single", "options": [{"id": "A", "text": "Button"}, {"id": "B", "text": "Text"}, {"id": "C", "text": "Image"}, {"id": "D", "text": "Icon"}], "answers": ["C"], "plain": true, "note": "", "explanation": "Image hiển thị ảnh trong Compose.", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-2-pathway-2/android-basics-compose-unit-2-pathway-2?hl=en", "title": "Google · Unit 2 · Pathway 2 · Đáp án đã kiểm chứng"}}, {"id": "google-u2-p2-q2", "text": "Alignment.Center centers UI components both horizontally and vertically.", "type": "single", "options": [{"id": "A", "text": "True"}, {"id": "B", "text": "False"}], "answers": ["A"], "plain": true, "note": "", "explanation": "Alignment.Center căn giữa theo cả hai trục.", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-2-pathway-2/android-basics-compose-unit-2-pathway-2?hl=en", "title": "Google · Unit 2 · Pathway 2 · Đáp án đã kiểm chứng"}}, {"id": "google-u2-p2-q3", "text": "Composable functions can store an object in memory using the ___ composable", "type": "single", "options": [{"id": "A", "text": "remember"}, {"id": "B", "text": "Column"}, {"id": "C", "text": "Modifier"}, {"id": "D", "text": "@Composable"}], "answers": ["A"], "plain": true, "note": "", "explanation": "remember giữ giá trị qua các lần recomposition ở cùng vị trí.", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-2-pathway-2/android-basics-compose-unit-2-pathway-2?hl=en", "title": "Google · Unit 2 · Pathway 2 · Đáp án đã kiểm chứng"}}, {"id": "google-u2-p2-q4", "text": "The debugger allows you to inspect variables when code execution has been suspended.", "type": "single", "options": [{"id": "A", "text": "True"}, {"id": "B", "text": "False"}], "answers": ["A"], "plain": true, "note": "", "explanation": "Khi dừng ở breakpoint có thể kiểm tra biến.", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-2-pathway-2/android-basics-compose-unit-2-pathway-2?hl=en", "title": "Google · Unit 2 · Pathway 2 · Đáp án đã kiểm chứng"}}, {"id": "google-u2-p2-q5", "text": "By using ___ values in a composable function, variables can be made into observables that schedule a recomposition when their value is changed.", "type": "single", "options": [{"id": "A", "text": "remember"}, {"id": "B", "text": "Modifier"}, {"id": "C", "text": "@Composable"}, {"id": "D", "text": "mutableStateOf"}], "answers": ["D"], "plain": true, "note": "", "explanation": "mutableStateOf tạo State quan sát được để Compose biết cần cập nhật UI.", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-2-pathway-2/android-basics-compose-unit-2-pathway-2?hl=en", "title": "Google · Unit 2 · Pathway 2 · Đáp án đã kiểm chứng"}}, {"id": "google-u2-p2-q6", "text": "The ___ composable places its children in a vertical sequence.", "type": "single", "options": [{"id": "A", "text": "Row"}, {"id": "B", "text": "Box"}, {"id": "C", "text": "Column"}, {"id": "D", "text": "Modifier"}], "answers": ["C"], "plain": true, "note": "", "explanation": "Column xếp con theo chiều dọc.", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-2-pathway-2/android-basics-compose-unit-2-pathway-2?hl=en", "title": "Google · Unit 2 · Pathway 2 · Đáp án đã kiểm chứng"}}, {"id": "google-u2-p2-q7", "text": "The ___ debugger feature allows you to navigate back up the call stack.", "type": "single", "options": [{"id": "A", "text": "Step over"}, {"id": "B", "text": "Step out"}, {"id": "C", "text": "Step into"}, {"id": "D", "text": "Resume program"}], "answers": ["B"], "plain": true, "note": "", "explanation": "Step out chạy đến khi thoát lời gọi hàm hiện tại để quay về caller.", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-2-pathway-2/android-basics-compose-unit-2-pathway-2?hl=en", "title": "Google · Unit 2 · Pathway 2 · Đáp án đã kiểm chứng"}}]}, {"number": 6, "title": "Unit 2 · Pathway 3 · Interacting with UI and state", "questions": [{"id": "google-u2-p3-q1", "text": "Jetpack Compose runs your composables for the first time, during ___ it will keep track of the composables that you call to describe your UI.", "type": "single", "options": [{"id": "A", "text": "Initial composition"}, {"id": "B", "text": "Recomposition"}, {"id": "C", "text": "State change"}, {"id": "D", "text": "App termination"}], "answers": ["A"], "plain": true, "note": "", "explanation": "Initial composition ghi nhận cây composable ban đầu.", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-2-pathway-3/android-basics-compose-unit-2-pathway-3?hl=en", "title": "Google · Unit 2 · Pathway 3 · Đáp án đã kiểm chứng"}}, {"id": "google-u2-p3-q2", "text": "The only way to modify a Composition is through recomposition.", "type": "single", "options": [{"id": "A", "text": "True"}, {"id": "B", "text": "False"}], "answers": ["A"], "plain": true, "note": "", "explanation": "UI đã composition được cập nhật thông qua recomposition.", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-2-pathway-3/android-basics-compose-unit-2-pathway-3?hl=en", "title": "Google · Unit 2 · Pathway 3 · Đáp án đã kiểm chứng"}}, {"id": "google-u2-p3-q3", "text": "___ is when Jetpack Compose re-executes the composables that may have changed in response to data changes.", "type": "single", "options": [{"id": "A", "text": "Initial composition"}, {"id": "B", "text": "Recomposition"}, {"id": "C", "text": "State change"}, {"id": "D", "text": "App termination"}], "answers": ["B"], "plain": true, "note": "", "explanation": "Recomposition thực thi lại composable bị ảnh hưởng bởi thay đổi dữ liệu.", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-2-pathway-3/android-basics-compose-unit-2-pathway-3?hl=en", "title": "Google · Unit 2 · Pathway 3 · Đáp án đã kiểm chứng"}}, {"id": "google-u2-p3-q4", "text": "___ in an application is any value that can change over time.", "type": "single", "options": [{"id": "A", "text": "State"}, {"id": "B", "text": "value"}, {"id": "C", "text": "valueChange"}, {"id": "D", "text": "StateValue"}], "answers": ["A"], "plain": true, "note": "", "explanation": "State là dữ liệu có thể thay đổi theo thời gian.", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-2-pathway-3/android-basics-compose-unit-2-pathway-3?hl=en", "title": "Google · Unit 2 · Pathway 3 · Đáp án đã kiểm chứng"}}, {"id": "google-u2-p3-q5", "text": "___ is a pattern of moving state up to make a component stateless.", "type": "single", "options": [{"id": "A", "text": "State change"}, {"id": "B", "text": "State hoisting"}, {"id": "C", "text": "Hoist composition"}, {"id": "D", "text": "Recomposition"}], "answers": ["B"], "plain": true, "note": "", "explanation": "State hoisting đưa quyền quản lý state lên caller.", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-2-pathway-3/android-basics-compose-unit-2-pathway-3?hl=en", "title": "Google · Unit 2 · Pathway 3 · Đáp án đã kiểm chứng"}}, {"id": "google-u2-p3-q6", "text": "Which KeyboardAction property is used to move the focus to the next composable?", "type": "single", "options": [{"id": "A", "text": "onDone"}, {"id": "B", "text": "onNext"}, {"id": "C", "text": "onGo"}, {"id": "D", "text": "onSend"}], "answers": ["B"], "plain": true, "note": "", "explanation": "onNext xử lý hành động Next để chuyển focus.", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-2-pathway-3/android-basics-compose-unit-2-pathway-3?hl=en", "title": "Google · Unit 2 · Pathway 3 · Đáp án đã kiểm chứng"}}, {"id": "google-u2-p3-q7", "text": "Which of the following Kotlin functions is used to round up a Double or Float?", "type": "single", "options": [{"id": "A", "text": "kotlin.math.ceilUp()"}, {"id": "B", "text": "kotlin.math.ceil()"}, {"id": "C", "text": "kotlin.math.roundDown()"}, {"id": "D", "text": "kotlin.math.roundUp()"}], "answers": ["B"], "plain": true, "note": "", "explanation": "ceil làm tròn về phía dương vô cùng.", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-2-pathway-3/android-basics-compose-unit-2-pathway-3?hl=en", "title": "Google · Unit 2 · Pathway 3 · Đáp án đã kiểm chứng"}}, {"id": "google-u2-p3-q8", "text": "Layout Inspector is a tool in Jetpack Compose that allows you to inspect a Compose layout inside a running app in an emulator or physical device.", "type": "single", "options": [{"id": "A", "text": "True"}, {"id": "B", "text": "False"}], "answers": ["A"], "plain": true, "note": "", "explanation": "Layout Inspector kiểm tra cây layout đang chạy.", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-2-pathway-3/android-basics-compose-unit-2-pathway-3?hl=en", "title": "Google · Unit 2 · Pathway 3 · Đáp án đã kiểm chứng"}}, {"id": "google-u2-p3-q9", "text": "UI tests are stored in the ___ directory.", "type": "single", "options": [{"id": "A", "text": "main"}, {"id": "B", "text": "androidTest"}, {"id": "C", "text": "test"}, {"id": "D", "text": "res"}], "answers": ["B"], "plain": true, "note": "", "explanation": "Instrumented UI tests nằm trong androidTest.", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-2-pathway-3/android-basics-compose-unit-2-pathway-3?hl=en", "title": "Google · Unit 2 · Pathway 3 · Đáp án đã kiểm chứng"}}, {"id": "google-u2-p3-q10", "text": "Local tests and UI tests should be annotated with the ___ annotation.", "type": "single", "options": [{"id": "A", "text": "@VisibleForTesting"}, {"id": "B", "text": "@Preview"}, {"id": "C", "text": "@Test"}, {"id": "D", "text": "@Composable"}], "answers": ["C"], "plain": true, "note": "", "explanation": "JUnit nhận diện phương thức kiểm thử bằng @Test.", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-2-pathway-3/android-basics-compose-unit-2-pathway-3?hl=en", "title": "Google · Unit 2 · Pathway 3 · Đáp án đã kiểm chứng"}}]}, {"number": 7, "title": "Unit 3 · Pathway 1 · More Kotlin fundamentals", "questions": [{"id": "google-u3-p1-q1", "text": "Which of the following is a valid way to define a data class in Kotlin?", "type": "single", "options": [{"id": "A", "text": "data class Person(val name: String, val age: Int)"}, {"id": "B", "text": "class Person(val name: String, val age: Int): data"}, {"id": "C", "text": "class Person (val name: String, val age: Int)"}, {"id": "D", "text": "data class Person{val name: String, val age: Int}"}], "answers": ["A"], "plain": true, "note": "", "explanation": "data class có primary constructor chứa các thuộc tính val hoặc var.", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-3-pathway-1/android-basics-compose-unit-3-pathway-1?hl=en", "title": "Google · Unit 3 · Pathway 1 · Đáp án đã kiểm chứng"}}, {"id": "google-u3-p1-q2", "text": "When using a sealed class, all direct subclasses must be in the same package.", "type": "single", "options": [{"id": "A", "text": "true"}, {"id": "B", "text": "false"}], "answers": ["A"], "plain": true, "note": "", "explanation": "Direct subclass của sealed class phải ở cùng package và module theo quy tắc Kotlin hiện tại.", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-3-pathway-1/android-basics-compose-unit-3-pathway-1?hl=en", "title": "Google · Unit 3 · Pathway 1 · Đáp án đã kiểm chứng"}}, {"id": "google-u3-p1-q3", "text": "When using generics, the generic data type goes inside ___.", "type": "single", "options": [{"id": "A", "text": "[]"}, {"id": "B", "text": "{}"}, {"id": "C", "text": "()"}, {"id": "D", "text": "<>"}], "answers": ["D"], "plain": true, "note": "", "explanation": "Tham số kiểu generic đặt trong dấu < >.", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-3-pathway-1/android-basics-compose-unit-3-pathway-1?hl=en", "title": "Google · Unit 3 · Pathway 1 · Đáp án đã kiểm chứng"}}, {"id": "google-u3-p1-q4", "text": "A(n) ___ class is useful when you have a fixed set of values.", "type": "single", "options": [{"id": "A", "text": "enum"}, {"id": "B", "text": "sealed"}, {"id": "C", "text": "data"}, {"id": "D", "text": "inherited"}], "answers": ["A"], "plain": true, "note": "", "explanation": "enum biểu diễn một tập hằng số cố định.", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-3-pathway-1/android-basics-compose-unit-3-pathway-1?hl=en", "title": "Google · Unit 3 · Pathway 1 · Đáp án đã kiểm chứng"}}, {"id": "google-u3-p1-q5", "text": "To create a list object that has the ability to change its size, you would call ___.", "type": "single", "options": [{"id": "A", "text": "modifiableListOf()"}, {"id": "B", "text": "immutableListOf()"}, {"id": "C", "text": "listOf()"}, {"id": "D", "text": "mutableListOf()"}], "answers": ["D"], "plain": true, "note": "", "explanation": "mutableListOf tạo MutableList có thể thêm và xóa phần tử.", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-3-pathway-1/android-basics-compose-unit-3-pathway-1?hl=en", "title": "Google · Unit 3 · Pathway 1 · Đáp án đã kiểm chứng"}}, {"id": "google-u3-p1-q6", "text": "Which of the following are higher-order functions?", "type": "multi", "options": [{"id": "A", "text": "map"}, {"id": "B", "text": "arrangeBy"}, {"id": "C", "text": "filter"}, {"id": "D", "text": "forEach"}], "answers": ["A", "C", "D"], "plain": true, "note": "", "explanation": "map, filter và forEach nhận hàm làm tham số. arrangeBy không phải hàm chuẩn ở đây.", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-3-pathway-1/android-basics-compose-unit-3-pathway-1?hl=en", "title": "Google · Unit 3 · Pathway 1 · Đáp án đã kiểm chứng"}}, {"id": "google-u3-p1-q7", "text": "Given the following line of code, which of the following commands will print Blue ? (Hint: If you are not sure, try running the code in the Kotlin Playground.)\n\nval colors = listOf(\"Red\", \"Green\", \"Blue\")", "type": "multi", "options": [{"id": "A", "text": "println(colors[2])"}, {"id": "B", "text": "println(colors.get(2))"}, {"id": "C", "text": "println(colors.contains(2))"}, {"id": "D", "text": "println(colors.getOrDefaultValue(index = 2, defaultValue = 10))"}], "answers": ["A", "B"], "plain": true, "note": "", "explanation": "Chỉ số danh sách bắt đầu từ 0 nên colors[2] và colors.get(2) lấy Blue.", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-3-pathway-1/android-basics-compose-unit-3-pathway-1?hl=en", "title": "Google · Unit 3 · Pathway 1 · Đáp án đã kiểm chứng"}}, {"id": "google-u3-p1-q8", "text": "The programming concept of a class that has only one instance is called a ___.", "type": "single", "options": [{"id": "A", "text": "Uniqueness"}, {"id": "B", "text": "Singleton"}, {"id": "C", "text": "Mono-object"}, {"id": "D", "text": "Lambda"}], "answers": ["B"], "plain": true, "note": "", "explanation": "Singleton là đối tượng có một instance.", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-3-pathway-1/android-basics-compose-unit-3-pathway-1?hl=en", "title": "Google · Unit 3 · Pathway 1 · Đáp án đã kiểm chứng"}}, {"id": "google-u3-p1-q9", "text": "Which of the following statements is true regarding sets and maps?", "type": "single", "options": [{"id": "A", "text": "A set must contain distinct values and a map’s keys must be distinct."}, {"id": "B", "text": "A set must contain distinct values and a map’s keys can contain duplicates."}, {"id": "C", "text": "A set can contain duplicate values and a map’s values can contain duplicate values."}, {"id": "D", "text": "A set can contain duplicate values and a map’s keys must be distinct."}], "answers": ["A"], "plain": true, "note": "", "explanation": "Set loại phần tử trùng, còn key trong Map phải duy nhất.", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-3-pathway-1/android-basics-compose-unit-3-pathway-1?hl=en", "title": "Google · Unit 3 · Pathway 1 · Đáp án đã kiểm chứng"}}, {"id": "google-u3-p1-q10", "text": "If you have a variable named records , which is a collection, to determine the number of items it contains, you can call ___.", "type": "single", "options": [{"id": "A", "text": "records.length"}, {"id": "B", "text": "records.quantity"}, {"id": "C", "text": "len(records)"}, {"id": "D", "text": "records.size"}], "answers": ["D"], "plain": true, "note": "", "explanation": "Collection.size là số phần tử.", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-3-pathway-1/android-basics-compose-unit-3-pathway-1?hl=en", "title": "Google · Unit 3 · Pathway 1 · Đáp án đã kiểm chứng"}}]}, {"number": 8, "title": "Unit 3 · Pathway 2 · Build a scrollable list", "questions": [{"id": "google-u3-p2-q1", "text": "Adaptive launcher icons for Android apps consist of a foreground and background vector drawable.", "type": "single", "options": [{"id": "A", "text": "True"}, {"id": "B", "text": "False"}], "answers": ["A"], "plain": true, "note": "", "explanation": "Trong bài học này, adaptive icon được tạo bằng foreground và background vector drawable. Android nói chung cũng cho phép drawable khác; vector không phải yêu cầu bắt buộc của mọi adaptive icon.", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-3-pathway-2/android-basics-compose-unit-3-pathway-2?hl=en", "title": "Google · Unit 3 · Pathway 2 · Đáp án đã kiểm chứng"}}, {"id": "google-u3-p2-q2", "text": "When building a UI that requires a scrolling list with a variable number of items, which Composable should you use?", "type": "single", "options": [{"id": "A", "text": "Column"}, {"id": "B", "text": "Row"}, {"id": "C", "text": "LazyColumn"}, {"id": "D", "text": "Card"}], "answers": ["C"], "plain": true, "note": "", "explanation": "LazyColumn dựng các phần tử cần thiết cho danh sách dọc cuộn.", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-3-pathway-2/android-basics-compose-unit-3-pathway-2?hl=en", "title": "Google · Unit 3 · Pathway 2 · Đáp án đã kiểm chứng"}}, {"id": "google-u3-p2-q3", "text": "What file type is used for the launcher icon foreground and background vectors?", "type": "single", "options": [{"id": "A", "text": ".txt"}, {"id": "B", "text": ".jpg"}, {"id": "C", "text": ".png"}, {"id": "D", "text": ".xml"}], "answers": ["D"], "plain": true, "note": "", "explanation": "Vector drawable được mô tả bằng XML.", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-3-pathway-2/android-basics-compose-unit-3-pathway-2?hl=en", "title": "Google · Unit 3 · Pathway 2 · Đáp án đã kiểm chứng"}}, {"id": "google-u3-p2-q4", "text": "Which Composable should you use to create a vertically scrollable grid with an undetermined number of items?", "type": "single", "options": [{"id": "A", "text": "LazyColumn"}, {"id": "B", "text": "LazyVerticalGrid"}, {"id": "C", "text": "LazyHorizontalGrid"}, {"id": "D", "text": "Row"}], "answers": ["B"], "plain": true, "note": "", "explanation": "LazyVerticalGrid bố trí lưới cuộn theo chiều dọc.", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-3-pathway-2/android-basics-compose-unit-3-pathway-2?hl=en", "title": "Google · Unit 3 · Pathway 2 · Đáp án đã kiểm chứng"}}, {"id": "google-u3-p2-q5", "text": "The Column composable is not a good option for a list of items of unknown quantity because ___.", "type": "single", "options": [{"id": "A", "text": "It can only hold a small, finite number of predefined items"}, {"id": "B", "text": "It arranges items vertically"}, {"id": "C", "text": "It provides scrolling by default without any additional code"}, {"id": "D", "text": "It can add content on demand"}], "answers": ["A"], "plain": true, "note": "", "explanation": "A là lựa chọn dự kiến của quiz. Cách diễn đạt bị đơn giản hóa: Column có thể nhận danh sách động nhưng dựng tất cả children và không tự cuộn. LazyColumn phù hợp hơn cho danh sách lớn hoặc chưa biết kích thước.", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-3-pathway-2/android-basics-compose-unit-3-pathway-2?hl=en", "title": "Google · Unit 3 · Pathway 2 · Đáp án đã kiểm chứng"}}, {"id": "google-u3-p2-q6", "text": "The ___ method is used to add content to a LazyColumn Composable.", "type": "single", "options": [{"id": "A", "text": "painterResource()"}, {"id": "B", "text": "Modifier.padding()"}, {"id": "C", "text": "items()"}, {"id": "D", "text": "onCreate()"}], "answers": ["C"], "plain": true, "note": "", "explanation": "items cung cấp nhiều phần tử cho LazyColumn.", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-3-pathway-2/android-basics-compose-unit-3-pathway-2?hl=en", "title": "Google · Unit 3 · Pathway 2 · Đáp án đã kiểm chứng"}}, {"id": "google-u3-p2-q7", "text": "Which Composable arranges items horizontally?", "type": "single", "options": [{"id": "A", "text": "Column"}, {"id": "B", "text": "Card"}, {"id": "C", "text": "Image"}, {"id": "D", "text": "Row"}], "answers": ["D"], "plain": true, "note": "", "explanation": "Row xếp theo chiều ngang.", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-3-pathway-2/android-basics-compose-unit-3-pathway-2?hl=en", "title": "Google · Unit 3 · Pathway 2 · Đáp án đã kiểm chứng"}}, {"id": "google-u3-p2-q8", "text": "Which Composable arranges items vertically?", "type": "single", "options": [{"id": "A", "text": "Column"}, {"id": "B", "text": "Card"}, {"id": "C", "text": "Image"}, {"id": "D", "text": "Row"}], "answers": ["A"], "plain": true, "note": "", "explanation": "Column xếp theo chiều dọc.", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-3-pathway-2/android-basics-compose-unit-3-pathway-2?hl=en", "title": "Google · Unit 3 · Pathway 2 · Đáp án đã kiểm chứng"}}]}, {"number": 9, "title": "Unit 3 · Pathway 3 · Build beautiful apps", "questions": [{"id": "google-u3-p3-q1", "text": "Animations in your Android app can:", "type": "single", "options": [{"id": "A", "text": "Add visual cues about what's going on in your app."}, {"id": "B", "text": "Add a polished look to your app."}, {"id": "C", "text": "Help the user see what changed."}, {"id": "D", "text": "All of the above."}], "answers": ["D"], "plain": true, "note": "", "explanation": "Animation có thể cung cấp tín hiệu, làm rõ thay đổi và tạo chuyển động trau chuốt.", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-3-pathway-3/android-basics-compose-unit-3-pathway-3?hl=en", "title": "Google · Unit 3 · Pathway 3 · Đáp án đã kiểm chứng"}}, {"id": "google-u3-p3-q2", "text": "Spring animation is based on:", "type": "single", "options": [{"id": "A", "text": "Start and end values over the specified duration."}, {"id": "B", "text": "Damping ratio and stiffness."}, {"id": "C", "text": "Snapshot values specified at different timestamps."}, {"id": "D", "text": "Interpolation between two keyframe values."}], "answers": ["B"], "plain": true, "note": "", "explanation": "Spring animation được cấu hình qua damping ratio và stiffness.", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-3-pathway-3/android-basics-compose-unit-3-pathway-3?hl=en", "title": "Google · Unit 3 · Pathway 3 · Đáp án đã kiểm chứng"}}, {"id": "google-u3-p3-q3", "text": "Spring animation is a physics-based animation driven by spring force.", "type": "single", "options": [{"id": "A", "text": "True"}, {"id": "B", "text": "False"}], "answers": ["A"], "plain": true, "note": "", "explanation": "Spring mô phỏng lực lò xo.", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-3-pathway-3/android-basics-compose-unit-3-pathway-3?hl=en", "title": "Google · Unit 3 · Pathway 3 · Đáp án đã kiểm chứng"}}, {"id": "google-u3-p3-q4", "text": "In the Material theming, the ___ color is the color displayed most frequently across your app's screens and components.", "type": "single", "options": [{"id": "A", "text": "primary"}, {"id": "B", "text": "secondary"}, {"id": "C", "text": "surface"}, {"id": "D", "text": "background"}], "answers": ["A"], "plain": true, "note": "", "explanation": "Trong cách mô tả Material của quiz, primary là màu thương hiệu được dùng thường xuyên.", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-3-pathway-3/android-basics-compose-unit-3-pathway-3?hl=en", "title": "Google · Unit 3 · Pathway 3 · Đáp án đã kiểm chứng"}}, {"id": "google-u3-p3-q5", "text": "The following file is used to define shapes of components in Compose.", "type": "single", "options": [{"id": "A", "text": "Theme.kt"}, {"id": "B", "text": "Color.kt"}, {"id": "C", "text": "Shape.kt"}, {"id": "D", "text": "Colors.kt"}], "answers": ["C"], "plain": true, "note": "", "explanation": "Shape.kt khai báo hình dạng component trong cấu trúc dự án bài học.", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-3-pathway-3/android-basics-compose-unit-3-pathway-3?hl=en", "title": "Google · Unit 3 · Pathway 3 · Đáp án đã kiểm chứng"}}, {"id": "google-u3-p3-q6", "text": "You can only have one @Preview composable", "type": "single", "options": [{"id": "A", "text": "True"}, {"id": "B", "text": "False"}], "answers": ["B"], "plain": true, "note": "", "explanation": "Có thể có nhiều @Preview để xem các cấu hình khác nhau.", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-3-pathway-3/android-basics-compose-unit-3-pathway-3?hl=en", "title": "Google · Unit 3 · Pathway 3 · Đáp án đã kiểm chứng"}}, {"id": "google-u3-p3-q7", "text": "A hex color code starts with a pound (#) character, and is followed by six letters and/or numbers that represent the red, green, and blue (RGB) components of that color.", "type": "single", "options": [{"id": "A", "text": "True"}, {"id": "B", "text": "False"}], "answers": ["A"], "plain": true, "note": "", "explanation": "RGB sáu chữ số biểu diễn ba kênh màu. Kotlin Color thường còn dùng alpha, ví dụ 0xFFRRGGBB.", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-3-pathway-3/android-basics-compose-unit-3-pathway-3?hl=en", "title": "Google · Unit 3 · Pathway 3 · Đáp án đã kiểm chứng"}}, {"id": "google-u3-p3-q8", "text": "The ___ file is the file that holds all the information about the theme of the app which is defined through color, shape, and typography.", "type": "single", "options": [{"id": "A", "text": "Theme.kt"}, {"id": "B", "text": "Color.kt"}, {"id": "C", "text": "Shape.kt"}, {"id": "D", "text": "Colors.kt"}], "answers": ["A"], "plain": true, "note": "", "explanation": "Theme.kt kết hợp color, shape và typography.", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-3-pathway-3/android-basics-compose-unit-3-pathway-3?hl=en", "title": "Google · Unit 3 · Pathway 3 · Đáp án đã kiểm chứng"}}, {"id": "google-u3-p3-q9", "text": "___  creates contrast between the Card and the background by adding a shadow to make the app look more realistic and visually interesting?", "type": "single", "options": [{"id": "A", "text": "Elevation"}, {"id": "B", "text": "Shape"}, {"id": "C", "text": "Color"}, {"id": "D", "text": "Theme"}], "answers": ["A"], "plain": true, "note": "", "explanation": "Elevation tạo bóng và cảm giác nổi khỏi nền.", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-3-pathway-3/android-basics-compose-unit-3-pathway-3?hl=en", "title": "Google · Unit 3 · Pathway 3 · Đáp án đã kiểm chứng"}}, {"id": "google-u3-p3-q10", "text": "What are reasons that someone may use Dark Theme on their device?", "type": "single", "options": [{"id": "A", "text": "It can reduce power usage by a significant amount (depending on the device’s screen technology)."}, {"id": "B", "text": "It improves visibility for users with low vision and those who are sensitive to bright light."}, {"id": "C", "text": "It makes it easier for anyone to use a device in a low-light environment."}, {"id": "D", "text": "All of the above."}], "answers": ["D"], "plain": true, "note": "", "explanation": "Cả ba lý do đều đúng; tiết kiệm điện còn tùy công nghệ màn hình.", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-3-pathway-3/android-basics-compose-unit-3-pathway-3?hl=en", "title": "Google · Unit 3 · Pathway 3 · Đáp án đã kiểm chứng"}}, {"id": "google-u3-p3-q11", "text": "TalkBack allows a user to navigate an app using switches instead of the touchscreen.", "type": "single", "options": [{"id": "A", "text": "True"}, {"id": "B", "text": "False"}], "answers": ["B"], "plain": true, "note": "", "explanation": "TalkBack là trình đọc màn hình. Điều khiển bằng switch thuộc Switch Access.", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-3-pathway-3/android-basics-compose-unit-3-pathway-3?hl=en", "title": "Google · Unit 3 · Pathway 3 · Đáp án đã kiểm chứng"}}, {"id": "google-u3-p3-q12", "text": "Which attribute allows TalkBack to speak a meaningful representation of an image or icon?", "type": "single", "options": [{"id": "A", "text": "elevation"}, {"id": "B", "text": "shape"}, {"id": "C", "text": "contentDescription"}, {"id": "D", "text": "style"}], "answers": ["C"], "plain": true, "note": "", "explanation": "contentDescription là mô tả ngữ nghĩa cho ảnh hoặc icon.", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-3-pathway-3/android-basics-compose-unit-3-pathway-3?hl=en", "title": "Google · Unit 3 · Pathway 3 · Đáp án đã kiểm chứng"}}]}];
